// Macaco pantográfico (tesoura) acionado por fuso — modelo puro.
// Topologia: base fixa com 2 pinos (x=±E, z=Z0); 2 braços inferiores com setores dentados que engrenam (mantêm simetria);
// pinos laterais (munhões) em x=±s: esquerdo = mancal liso + colar axial do fuso, direito = porca roscada;
// 2 braços superiores com setores dentados até 2 pinos na sapata (z=ZT). Fuso ao longo de x em y=0, z=zS.
// Pilha axial em y (mm): munhão |y|<=20 · flange sup. 21.5–24.5 · cabeça sapata 25–28 · flange inf. 26–29 · bochecha base 30–33.
// Câmera vê de +x,+y,+z: camadas em y são pintadas de -y para +y; manivela (x mínimo) antes; prato da sapata (z máximo) depois.
import { externalGearPair } from '/leitor/mechanics.mjs';

export const D = {
  L: 200, E: 22, pitch: 3, nMax: 80, Z0: 36, aMax: 180,
  bh: 16, bz: 15, by: 20, washer: 3, collar: 10, hub: 34, screwLen: 500, rMajor: 7, rMinor: 5.5,
  crankR: 70, handleLen: 55, hw: 13, pinR: 5, gearM: 2.4, gearZ: 20, padGap: 27, padH: 16,
  y: { blockHalf: 20, upper: [21.5, 24.5], saddle: [25, 28], lower: [26, 29], cheek: [30, 33], stub: [14, 33], pinEnd: 35 }
};
export const PAIR = externalGearPair({ teethA: D.gearZ, teethB: D.gearZ, module: D.gearM, backlash: 0.15 });
D.E = PAIR.distance / 2;

export function pose(turns) {
  const n = Math.min(D.nMax, Math.max(0, turns));
  const s = D.E + D.aMax - (D.pitch * n) / 2;          // cada volta encurta 2s de um passo
  const a = s - D.E, v = Math.sqrt(D.L * D.L - a * a), phi = Math.atan2(v, a);
  const zS = D.Z0 + v, zT = D.Z0 + 2 * v;
  const xCollar0 = -s - D.bh - D.washer - D.collar;    // colar encosta na arruela externa do mancal
  const xL = xCollar0 - D.hub, tip = xL + D.screwLen;
  const theta = 2 * Math.PI * n;                        // +x (mão direita) = horário visto da manivela = subir
  const pins = {
    bl: [-D.E, D.Z0], br: [D.E, D.Z0], sl: [-s, zS], sr: [s, zS], tl: [-D.E, zT], tr: [D.E, zT]
  };
  const arms = [
    { id: 'LL', from: pins.bl, to: pins.sl, gear: Math.PI - phi, layer: D.y.lower, interior: [0, zS] },
    { id: 'LR', from: pins.br, to: pins.sr, gear: phi + Math.PI / D.gearZ, layer: D.y.lower, interior: [0, zS] },
    { id: 'UL', from: pins.tl, to: pins.sl, gear: Math.PI + phi, layer: D.y.upper, interior: [0, zS] },
    { id: 'UR', from: pins.tr, to: pins.sr, gear: Math.PI / D.gearZ - phi, layer: D.y.upper, interior: [0, zS] }
  ];
  return {
    n, s, a, v, phi, zS, zT, pins, arms, theta, xL, tip, xCollar0, threadX0: xL - (D.pitch * theta) / (2 * Math.PI),
    padTop: zT + D.padGap + D.padH, span: 2 * s,
    nut: [s - D.bh, s + D.bh], thread: [-s - D.bh, tip - 3], bearing: [-s - D.bh, -s + D.bh]
  };
}
// Alma do perfil U (lado externo do losango), em xz; ocupa |y| <= layer[1]. Consumida pela geometria.
export function webRect(arm) {
  const [A, B] = [arm.from, arm.to], L = Math.hypot(B[0] - A[0], B[1] - A[1]);
  const d = [(B[0] - A[0]) / L, (B[1] - A[1]) / L];
  let n = [-d[1], d[0]];
  const mid = [(A[0] + B[0]) / 2, (A[1] + B[1]) / 2];
  if ((arm.interior[0] - mid[0]) * n[0] + (arm.interior[1] - mid[1]) * n[1] > 0) n = [-n[0], -n[1]];
  const P = (t, o) => [A[0] + d[0] * t + n[0] * o, A[1] + d[1] * t + n[1] * o];
  return [P(32, D.hw - 3.5), P(L - 34, D.hw - 3.5), P(L - 34, D.hw), P(32, D.hw)];
}
export const liftPerTurn = (n) => { const h = 1e-3, a = pose(Math.max(0, n - h)), b = pose(Math.min(D.nMax, n + h)); return (b.padTop - a.padTop) / ((b.n - a.n) || 1); };

export const init = () => ({ turns: 0, playing: false, dir: 1, cut: false, limit: '' });
// Gira a manivela dTurns voltas (positivo = horário = subir). Respeita fim de curso.
export function advance(st, dTurns) {
  const want = st.turns + dTurns, turns = Math.min(D.nMax, Math.max(0, want));
  let limit = '';
  if (want > D.nMax + 1e-9 || (turns >= D.nMax && dTurns > 0)) limit = 'top';
  if (want < -1e-9 || (turns <= 0 && dTurns < 0)) limit = 'bottom';
  return { ...st, turns, limit, playing: limit ? false : st.playing };
}
// Reprodução no tempo: dtSec (s) de quadro × voltas/s. Pausado = estado intacto (parada estável).
export const PLAY = { rate: 4, rateReduced: 2, maxDt: 0.1 };
export function playStep(st, dtSec, rate = PLAY.rate) {
  if (!st.playing) return st;
  const dt = Math.min(PLAY.maxDt, Math.max(0, dtSec));
  return advance(st, st.dir * dt * rate);
}
export const setDir = (st, dir) => ({ ...st, dir: dir >= 0 ? 1 : -1, limit: '' });
export const togglePlay = (st) => ({ ...st, playing: !st.playing, limit: '' });
export const toggleCut = (st) => ({ ...st, cut: !st.cut });
export const reset = (st) => ({ ...init(), cut: false });

