import { D, PAIR, pose, advance, init, togglePlay, setDir, liftPerTurn } from './model.mjs';

const rot = (pts, g, c) => pts.map(([x, y]) => [c[0] + x * Math.cos(g) - y * Math.sin(g), c[1] + x * Math.sin(g) + y * Math.cos(g)]);
function inside(p, poly) {
  let k = false;
  for (let i = 0, j = poly.length - 1; i < poly.length; j = i++) {
    const a = poly[i], b = poly[j];
    if ((a[1] > p[1]) !== (b[1] > p[1]) && p[0] < ((b[0] - a[0]) * (p[1] - a[1])) / (b[1] - a[1]) + a[0]) k = !k;
  }
  return k;
}
const ov = (a, b) => Math.min(a[1], b[1]) - Math.max(a[0], b[0]);

export function verify() {
  const out = [], add = (name, passed, detail = '') => out.push({ name, passed: !!passed, detail });
  const N = 41, samples = Array.from({ length: N }, (_, i) => (D.nMax * i) / (N - 1));
  let armErr = 0, sym = 0, pinZ = 0, prevTop = -Infinity, mono = true, eng = Infinity, gearHit = 0, gearGap = Infinity, ground = Infinity, crankClear = Infinity;
  const pts = PAIR.first.outline;
  for (const n of samples) {
    const p = pose(n);
    for (const a of p.arms) armErr = Math.max(armErr, Math.abs(Math.hypot(a.to[0] - a.from[0], a.to[1] - a.from[1]) - D.L));
    sym = Math.max(sym, Math.abs(p.pins.sl[0] + p.pins.sr[0]), Math.abs(p.pins.sl[1] - p.pins.sr[1]));
    pinZ = Math.max(pinZ, Math.abs(p.zS - (p.pins.bl[1] + p.pins.tl[1]) / 2));
    if (p.padTop < prevTop) mono = false; prevTop = p.padTop;
    eng = Math.min(eng, ov(p.nut, p.thread), ov(p.bearing, p.thread));
    // engrenamento dos setores: nenhum vértice de um dente dentro do outro
    for (const [A, B] of [[p.arms[0], p.arms[1]], [p.arms[2], p.arms[3]]]) {
      const ga = rot(pts, A.gear, A.from), gb = rot(PAIR.second.outline, B.gear, B.from);
      const near = (q) => Math.abs(q[0]) < 6 && Math.abs(q[1] - A.from[1]) < 8;
      for (const q of ga) if (near(q) && inside(q, gb)) gearHit++;
      for (const q of gb) if (near(q) && inside(q, ga)) gearHit++;
      let m = Infinity;
      for (const q of ga) if (near(q)) for (const r of gb) if (near(r)) m = Math.min(m, Math.hypot(q[0] - r[0], q[1] - r[1]));
      gearGap = Math.min(gearGap, m);
    }
    ground = Math.min(ground, p.zS - D.crankR - 14);
    crankClear = Math.min(crankClear, (-p.s - 14) - (p.xL + D.hub));
  }
  add('Quatro braços mantêm 200 mm entre pinos', armErr < 1e-9, `erro máx ${armErr.toExponential(2)} mm`);
  add('Losango simétrico: pinos laterais espelhados', sym < 1e-9, `${sym}`);
  add('Fuso na altura média entre pinos base e sapata', pinZ < 1e-9, `${pinZ}`);
  add('Sapata sobe monotonicamente com as voltas', mono);
  add('Rosca engata porca e mancal em todo curso', eng > 25, `engajamento mín ${eng.toFixed(1)} mm`);
  add('Setores dentados sem interpenetração', gearHit === 0, `${gearHit} vértices`);
  add('Setores dentados em contato (folga < 1,5 mm)', gearGap < 1.5, `folga mín ${gearGap.toFixed(2)} mm`);
  add('Manivela não toca o chão', ground > 0, `${ground.toFixed(1)} mm`);
  add('Cubo da manivela fora dos braços', crankClear > 0, `${crankClear.toFixed(1)} mm`);
  const p0 = pose(0), p1 = pose(D.nMax);
  add('Curso total coerente com 80 voltas × 3 mm', Math.abs((p0.span - p1.span) - D.nMax * D.pitch) < 1e-9, `${(p0.span - p1.span).toFixed(1)} mm`);
  add('Ângulo do braço dentro de 20°–80°', p0.phi > 0.35 && p1.phi < 1.4, `${(p0.phi * 57.3).toFixed(1)}°–${(p1.phi * 57.3).toFixed(1)}°`);
  // transições de estado
  let st = init();
  const down = advance(st, -1);
  add('Abaixo do curso inferior é bloqueado', down.turns === 0 && down.limit === 'bottom');
  st = advance(st, 10);
  add('Dez voltas sobem a sapata', pose(st.turns).padTop > p0.padTop + 10 && st.limit === '', `${(pose(st.turns).padTop - p0.padTop).toFixed(1)} mm`);
  const top = advance(togglePlay(st), 500);
  add('Fim de curso superior para a reprodução', top.turns === D.nMax && top.limit === 'top' && !top.playing);
  const back = advance(setDir(top, -1), -5);
  add('Sentido inverso desce após o limite', back.turns === D.nMax - 5 && back.limit === '');
  add('Ganho por volta maior no início do curso', liftPerTurn(1) > liftPerTurn(79), `${liftPerTurn(1).toFixed(2)} vs ${liftPerTurn(79).toFixed(2)} mm/volta`);
  let phDrift = 0; const ph0 = pose(0).threadX0 - pose(0).s;
  for (const n of samples) { const q = pose(n), d = q.threadX0 - q.s - ph0; phDrift = Math.max(phDrift, Math.abs(d - D.pitch * Math.round(d / D.pitch))); }
  add('Hélice do fuso parada em relação à porca (rosca coerente)', phDrift < 1e-6, `deriva ${phDrift.toExponential(2)} mm`);
  return out;
}

// 3D: fuso (cilindro r=rMajor em y=0,z=zS) x almas dos braços (|y|<=flange), bloco do mancal x flanges.
import { webRect } from './model.mjs';
export function verifyExtra1() {
  const out = [], add = (name, passed, detail = '') => out.push({ name, passed: !!passed, detail });
  let webClear = Infinity, crossed = 0, blockClear = Infinity, crankBase = Infinity;
  for (let i = 0; i <= 80; i++) {
    const p = pose((D.nMax * i) / 80), x0 = p.thread[0] - 40, x1 = p.tip;
    for (const a of p.arms) {
      const r = webRect(a);
      let above = 0, below = 0;
      for (let e = 0; e < 4; e++) for (let t = 0; t <= 20; t++) {
        const P0 = r[e], P1 = r[(e + 1) % 4], q = [P0[0] + (P1[0] - P0[0]) * t / 20, P0[1] + (P1[1] - P0[1]) * t / 20];
        if (q[0] < x0 || q[0] > x1) continue;
        const dz = q[1] - p.zS; webClear = Math.min(webClear, Math.abs(dz) - D.rMajor); if (dz > 0) above++; else below++;
      }
      if (above && below) crossed++;
      // ponto mais próximo da alma ao bloco do mancal (x em bearing, |z-zS|<=bz) — só relevante se |y| se sobrepõem
      for (const q of r) if (q[0] > p.bearing[0] && q[0] < p.bearing[1] && Math.abs(q[1] - p.zS) < D.bz) blockClear = Math.min(blockClear, -1);
    }
    crankBase = Math.min(crankBase, p.zS - D.crankR - 9 - 13);
  }
  add('Almas dos braços não cruzam o fuso (3D)', crossed === 0 && webClear > 0, `folga mín ${webClear.toFixed(1)} mm`);
  add('Almas fora do bloco do mancal (3D)', blockClear === Infinity);
  add('Flanges dos braços superiores fora do munhão (y)', D.y.upper[0] - D.y.blockHalf > 0.5, `${(D.y.upper[0] - D.y.blockHalf).toFixed(1)} mm`);
  add('Pega da manivela acima da base em todo giro', crankBase > 0, `${crankBase.toFixed(1)} mm`);
  return out;
}

// Reprodução temporal: quadros de ~16,7 ms acumulam movimento real; pausa estável; inversão; fins de curso; reinício.
import { playStep, PLAY, reset as resetSt, toggleCut } from './model.mjs';
export function verifyExtra2() {
  const out = [], add = (name, passed, detail = '') => out.push({ name, passed: !!passed, detail });
  // simula o agendador: timestamps crescentes, base de tempo preservada entre quadros
  const run = (st, count, rate, t0 = 1000) => { let last = 0; for (let i = 0; i < count; i++) { const t = t0 + i * 16.7; const dt = (t - (last || t)) / 1000; last = t; st = playStep(st, dt, rate); } return st; };
  let st = togglePlay(advance(init(), 20));
  const h0 = pose(st.turns).padTop, a1 = run(st, 120, PLAY.rateReduced);
  add('Reproduzir 2 s gira a manivela e sobe a sapata', a1.turns > st.turns + 3 && pose(a1.turns).padTop > h0 + 5 && a1.playing,
    `${st.turns.toFixed(1)}→${a1.turns.toFixed(2)} voltas, +${(pose(a1.turns).padTop - h0).toFixed(1)} mm`);
  const pz = togglePlay(a1), pz2 = run(pz, 120, PLAY.rate), dn = run(togglePlay(setDir(pz2, -1)), 120, PLAY.rate);
  add('Pausa estável; descer reduz voltas e altura no tempo', !pz.playing && pz2.turns === pz.turns && dn.turns < pz2.turns - 3 && pose(dn.turns).padTop < pose(pz2.turns).padTop, `${pz2.turns.toFixed(2)}→${dn.turns.toFixed(2)} voltas`);
  const bot = run(dn, 2000, PLAY.rate);
  const tp = run(togglePlay(setDir(bot, 1)), 3000, PLAY.rate);
  const r = resetSt(toggleCut(tp));
  const big = playStep(togglePlay(advance(init(), 10)), 5, PLAY.rate);
  add('Reprodução para nos fins de curso; reiniciar volta a 0', bot.turns === 0 && bot.limit === 'bottom' && !bot.playing
    && tp.turns === D.nMax && tp.limit === 'top' && !tp.playing && r.turns === 0 && !r.playing && !r.cut && r.dir === 1
    && big.turns - 10 <= PLAY.maxDt * PLAY.rate + 1e-9, `salto máx ${(big.turns - 10).toFixed(2)} voltas`);
  return out;
}

