import { D, pose, init, advance, setDir, togglePlay, toggleCut, reset, liftPerTurn, playStep, PLAY } from './model.mjs';
import { camera, draw } from './geometry.mjs';

const f1 = (v) => v.toFixed(1).replace('.', ',');

export function mount(root, env) {
  let st = init(), raf = 0, last = 0, visible = true, P = null, W = 0;
  root.innerHTML = `<div class="jk">
  <div class="jk-art"><svg id="jk-svg" role="img" aria-label="Macaco pantográfico em perspectiva isométrica"></svg></div>
  <div class="jk-read" aria-live="polite">
    <div><span>Voltas</span><b id="jk-turns"></b></div>
    <div><span>Altura da sapata</span><b id="jk-h"></b></div>
    <div><span>Distância entre articulações laterais</span><b id="jk-span"></b></div>
    <div><span>Subida por volta</span><b id="jk-rate"></b></div>
  </div>
  <p class="jk-status" id="jk-status" role="status"></p>
  <div class="jk-ctl">
    <button id="jk-down" type="button">↶ Descer 1 volta</button>
    <button id="jk-up" type="button">↷ Subir 1 volta</button>
    <button id="jk-play" type="button"></button>
    <button id="jk-dir" type="button"></button>
    <button id="jk-cut" type="button" aria-pressed="false"></button>
    <button id="jk-reset" type="button">Reiniciar</button>
    <label class="jk-range">Voltas da manivela <input id="jk-range" type="range" min="0" max="${D.nMax}" step="1" value="0"></label>
  </div>
  <ol class="jk-legend">
    <li><b>Base apoiada</b> com duas bochechas e pinos inferiores.</li>
    <li><b>Quatro braços</b> em perfil U (200 mm entre pinos); setores dentados mantêm o losango simétrico.</li>
    <li><b>Mancal liso</b> (esquerda): o colar empurra o fuso; <b>porca</b> (direita) recebe a rosca.</li>
    <li><b>Fuso</b> M14 × 3 mm e <b>manivela</b> R 70 mm presa por pino.</li>
    <li><b>Sapata</b> com ranhura central, articulada nos pinos superiores.</li>
  </ol>
</div>`;
  const $ = (id) => root.querySelector('#' + id), svg = $('jk-svg');
  function frame() {
    const w = Math.max(320, Math.min(900, root.clientWidth || 600)), h = Math.round(w < 560 ? w * 0.92 : w * 0.6);
    if (w !== W) { W = w; P = camera(w, h); svg.setAttribute('viewBox', P.vb); }
  }
  function paint() {
    frame();
    const p = pose(st.turns);
    svg.innerHTML = draw(st, P);
    $('jk-turns').textContent = `${f1(st.turns)} / ${D.nMax}`;
    $('jk-h').textContent = `${Math.round(p.padTop)} mm`;
    $('jk-span').textContent = `${Math.round(p.span)} mm`;
    $('jk-rate').textContent = `${f1(liftPerTurn(st.turns))} mm`;
    $('jk-play').textContent = st.playing ? '❚❚ Pausar' : '▶ Reproduzir';
    $('jk-dir').textContent = st.dir > 0 ? 'Sentido: subir' : 'Sentido: descer';
    $('jk-cut').textContent = st.cut ? 'Corte do fuso: ligado' : 'Corte do fuso: desligado';
    $('jk-cut').setAttribute('aria-pressed', String(st.cut));
    $('jk-range').value = String(Math.round(st.turns));
    $('jk-status').textContent = st.limit === 'top' ? `Fim de curso superior: ${D.nMax} voltas, sapata a ${Math.round(p.padTop)} mm.`
      : st.limit === 'bottom' ? 'Fim de curso inferior: o macaco já está totalmente fechado.'
      : st.playing ? `Girando para ${st.dir > 0 ? 'subir' : 'descer'}…` : `Parado em ${f1(st.turns)} voltas.`;
  }
  const set = (s) => { st = s; paint(); loop(); };
  function tick(t) {
    raf = 0;
    if (!st.playing || !visible) return;
