import * as k from '/kit/iso-kit.mjs';
import * as G from '/kit/lathe.mjs';
import { mPrism, mItems, mSvg, mGroove } from '/kit/facets.mjs';
import { D, PAIR, pose, webRect } from './model.mjs';

const FY = { o: [0, 0, 0], a: [0, 1, 0], u: [1, 0, 0], v: [0, 0, -1] };
const yPrism = (ring, y0, y1, tone = 'hi', cap = false) => {
  const m = mPrism([ring.map(([x, z]) => [x, -z])], FY, y0, y1, { tone });
  if (cap) m.faces[1].fill = 'cut';
