};
const items = (m, P) => mItems(m, P)[0];
const wrap = (a) => Math.atan2(Math.sin(a), Math.cos(a));

export function camera(w, h) {
  const pts = [];
  pts.push(...k.boxCorners({ x: -125, y: -48, w: 250, d: 96 }, 0, 13));
  for (const n of [0, D.nMax]) {
    const p = pose(n);
    pts.push(...k.boxCorners({ x: -46, y: -35, w: 92, d: 70 }, p.zT, p.padTop));
    for (const sx of [-1, 1]) pts.push(...k.boxCorners({ x: sx * p.s - 20, y: -35, w: 40, d: 70 }, p.zS - 20, p.zS + 20));
    for (let i = 0; i < 12; i++) { const a = (i * Math.PI) / 6; pts.push([p.tip + 6, 10 * Math.cos(a), p.zS + 10 * Math.sin(a)]); }
    for (let i = 0; i < 36; i++) {
      const a = (i * Math.PI) / 18, r = D.crankR + 14;
      for (const x of [p.xL - D.handleLen - 6, p.xL + 8]) pts.push([x, r * Math.cos(a), p.zS + r * Math.sin(a)]);
    }
  }
  const P = k.fitProjection(pts, w, h, { pad: 14, azimuth: 42, elevation: 30 });
  const s = pts.map((q) => k.iso(q, P)), xs = s.map((q) => q[0]), ys = s.map((q) => q[1]);
  const x0 = Math.min(...xs) - 8, y0 = Math.min(...ys) - 8;
  P.vb = `${x0.toFixed(1)} ${y0.toFixed(1)} ${(Math.max(...xs) - x0 + 8).toFixed(1)} ${(Math.max(...ys) - y0 + 8).toFixed(1)}`;
  return P;
}

function armRing(arm) {
  const [A, B] = [arm.from, arm.to], ang = Math.atan2(B[1] - A[1], B[0] - A[0]), hw = D.hw;
  const beta = A[0] < 0 ? 0 : Math.PI, win = (40 * Math.PI) / 180;
  const ring = [];
  for (let i = 0; i <= 10; i++) { const t = ang - Math.PI / 2 + (Math.PI * i) / 10; ring.push([B[0] + hw * Math.cos(t), B[1] + hw * Math.sin(t)]); }
  const rel = (a) => { let r = (((a - ang) * 180) / Math.PI) % 360; return r < 0 ? r + 360 : r; };
  const near = [];
  for (let d = 80; d <= 280; d += 8) {
    const a = ang + (d * Math.PI) / 180;
    if (Math.abs(wrap(a - beta)) > win) near.push([d, [A[0] + hw * Math.cos(a), A[1] + hw * Math.sin(a)]]);
  }
  const out = A[0] < 0 ? PAIR.first.outline : PAIR.second.outline, c = Math.cos(arm.gear), s = Math.sin(arm.gear);
  for (const [x, y] of out) {
    const p = [A[0] + x * c - y * s, A[1] + x * s + y * c], a = Math.atan2(p[1] - A[1], p[0] - A[0]), r = rel(a);
    if (Math.abs(wrap(a - beta)) <= win && r >= 80 && r <= 280) near.push([r, p]);
  }
  near.sort((a, b) => a[0] - b[0]);
  return ring.concat(near.map((q) => q[1]));
}
function webRing(arm) { return webRect(arm); }
function webRingOld(arm) {
  const [A, B] = [arm.from, arm.to], L = Math.hypot(B[0] - A[0], B[1] - A[1]);
  const d = [(B[0] - A[0]) / L, (B[1] - A[1]) / L];
  let n = [-d[1], d[0]];
  const mid = [(A[0] + B[0]) / 2, (A[1] + B[1]) / 2];
  if ((arm.interior[0] - mid[0]) * n[0] + (arm.interior[1] - mid[1]) * n[1] > 0) n = [-n[0], -n[1]];
  const P = (t, o) => [A[0] + d[0] * t + n[0] * o, A[1] + d[1] * t + n[1] * o];
  return [P(32, D.hw - 3.5), P(L - 34, D.hw - 3.5), P(L - 34, D.hw), P(32, D.hw)];
}
const roundRect = (x0, x1, z0, z1, r) => {
  const pts = [];
  for (const [cx, cz, a0] of [[x1 - r, z0 + r, -90], [x1 - r, z1 - r, 0], [x0 + r, z1 - r, 90], [x0 + r, z0 + r, 180]])
    for (let i = 0; i <= 4; i++) { const a = ((a0 + 22.5 * i) * Math.PI) / 180; pts.push([cx + r * Math.cos(a), cz + r * Math.sin(a)]); }
  return pts;
};
const discY = (x, z, y0, y1, r, P) => k.solidSvg(G.disc(y0, y1, r, G.frameAlong([x, 0, z], [0, 1, 0]), P), { tone: 'mid' });
const thr = (x, c) => { const u = ((((x - c) / D.pitch) % 1) + 1) % 1, dd = Math.min(u, 1 - u) * 2; return D.rMajor - (D.rMajor - D.rMinor) * Math.min(1, dd * 1.3); };

function screwPiece(p, x0, x1, P) {
  if (x1 - x0 < 0.5) return '';
  const F = G.frameAlong([0, 0, p.zS], [1, 0, 0]);
  let s = k.solidSvg(G.lathe([[x0, D.rMajor - 0.4], [x1, D.rMajor - 0.4]], F, P), { tone: 'mid' });
  const V = [Math.cos(0.733) * 0.866, Math.sin(0.733) * 0.866, 0.5];
  let crest = [], cur = [];
  const w0 = ((x0 - p.threadX0) / D.pitch) * 2 * Math.PI, w1 = ((x1 - p.threadX0) / D.pitch) * 2 * Math.PI;
  for (let w = w0; w <= w1; w += 0.3) {
    const cy = Math.cos(w), cz = Math.sin(w);
    if (cy * V[1] + cz * V[2] > 0.05) cur.push(k.iso([p.threadX0 + (D.pitch * w) / (2 * Math.PI), D.rMajor * cy, p.zS + D.rMajor * cz], P));
    else if (cur.length) { crest.push(cur); cur = []; }
  }
  if (cur.length) crest.push(cur);
  s += `<path class="jk-thread" d="${crest.map((c) => k.pathOf(c)).join('')}"/>`;
  return s;
}
function screwSection(p, x0, x1, P, nut) {
  const top = [], bot = [], nt = [], nb = [];
  const ct = p.threadX0 + D.pitch / 4, cb = p.threadX0 - D.pitch / 4;
  for (let x = x0; x <= x1 + 1e-6; x += 0.25) {
    const rt = thr(x, ct), rb = thr(x, cb);
    top.push([x, p.zS + rt]); bot.push([x, p.zS - rb]);
    nt.push([x, p.zS + (nut ? rt + 0.4 : D.rMajor + 0.5)]); nb.push([x, p.zS - (nut ? rb + 0.4 : D.rMajor + 0.5)]);
  }
  const sec = top.concat(bot.reverse());
  const flat = (r) => k.pathOf(r.map(([x, z]) => k.iso([x, 0, z], P)), true);
  const upper = nt.concat([[x1, p.zS + D.bz], [x0, p.zS + D.bz]]);
  const lower = nb.concat([[x1, p.zS - D.bz], [x0, p.zS - D.bz]]);
  return `<path class="lk-cut jk-sec" d="${flat(upper)}${flat(lower)}"/><path class="jk-screwcut" d="${flat(sec)}"/>`;
}

export function draw(st, P) {
  const p = pose(st.turns), cut = st.cut, out = [];
  const Y = (y) => (cut ? Math.min(y, 0) : y);
  // crank
  const th = p.theta, cy = Math.cos(th), cz = Math.sin(th);
  const hp = [p.xL, D.crankR * cy, p.zS + D.crankR * cz];
  const Fx = { o: [0, 0, p.zS], a: [1, 0, 0], u: [0, 1, 0], v: [0, 0, 1] };
  const armR = [];
  for (let i = 0; i <= 8; i++) { const a = th + Math.PI / 2 + (Math.PI * i) / 8; armR.push([12 * Math.cos(a), 12 * Math.sin(a)]); }
  for (let i = 0; i <= 8; i++) { const a = th - Math.PI / 2 + (Math.PI * i) / 8; armR.push([D.crankR * cy + 8 * Math.cos(a), D.crankR * cz + 8 * Math.sin(a)]); }
  const crankHandle = k.solidSvg(G.lathe([[p.xL - D.handleLen, 5], [p.xL - D.handleLen + 3, 7, 1], [p.xL - 28, 8, 1], [p.xL - 6, 7, 1], [p.xL, 5]], G.frameAlong([0, hp[1], hp[2]], [1, 0, 0]), P), { tone: 'lo' });
