  out.push(behind ? crankHandle + crankArm : crankArm);
  out.push(k.solidSvg(G.lathe([[p.xL, 11], [p.xL + 2, 12], [p.xCollar0 - 2, 12], [p.xCollar0, 10]], G.frameAlong([0, 0, p.zS], [1, 0, 0]), P), { tone: 'mid' }));
  out.push(`<path class="jk-pin" d="${k.pathOf([k.iso([p.xL + 20, 13 * cy, p.zS + 13 * cz], P), k.iso([p.xL + 20, -13 * cy, p.zS - 13 * cz], P)])}"/>`);
  if (!behind) out.push(crankHandle);
  // base
  const baseRing = roundRect(-125, 125, 0, 9, 4);
  out.push(mSvg(items(yPrism(baseRing, -48, Y(48), 'lo', cut), P)));
  out.push(mSvg(items(yPrism(roundRect(-60, 60, 9, 13, 2), -40, Y(40), 'lo', cut), P)));
  const cheek = [[-D.E - 34, 13], [D.E + 34, 13], [D.E + 16, D.Z0 + 10], [D.E + 8, D.Z0 + 15], [-D.E - 8, D.Z0 + 15], [-D.E - 16, D.Z0 + 10]];
  const sad = (zT) => [[-D.E - 14, zT - 12], [D.E + 14, zT - 12], [D.E + 22, zT + D.padGap], [-D.E - 22, zT + D.padGap]];
  const pinsAll = [[p.pins.bl, 33, 35, 8], [p.pins.br, 33, 35, 8], [p.pins.tl, 28, 30, 7], [p.pins.tr, 28, 30, 7], [p.pins.sl, 29, 35, 7.5], [p.pins.sr, 29, 35, 7.5]];
  const lowers = p.arms.filter((a) => a.id[0] === 'L'), uppers = p.arms.filter((a) => a.id[0] === 'U');
  const side = (sg) => {
    const L = (r) => (sg < 0 ? [-r[1], -r[0]] : r);
