    const heads = pinsAll.map(([q, a, b, r]) => discY(q[0], q[1], ...L([a, b]), r, P)).join('');
    const g2 = [];
    for (const a of lowers) g2.push(...items(yPrism(armRing(a), ...L(D.y.lower), 'hi'), P));
    g2.push(...items(yPrism(sad(p.zT), ...L(D.y.saddle), 'lo'), P));
    const g3 = []; for (const a of uppers) g3.push(...items(yPrism(armRing(a), ...L(D.y.upper), 'hi'), P));
    return { outer: g1.join('') + heads, lower: mSvg(g2), upper: mSvg(g3) };
  };
  const neg = side(-1);
