  // middle
  const yb = cut ? 0 : 26, yt = cut ? 0 : 21.5;
  for (const q of [p.pins.bl, p.pins.br]) out.push(discY(q[0], q[1], -26, yb, D.pinR, P));
  for (const q of [p.pins.tl, p.pins.tr]) out.push(discY(q[0], q[1], -21.5, yt, D.pinR, P));
  out.push(mSvg(lowers.flatMap((a) => items(yPrism(webRing(a), -D.y.lower[1], Y(D.y.lower[1]), 'hi', cut), P))));
